/* Curves Workshop · figures/cissoid.js — Figs. 23–26 (pages 26–28)
 *
 * Fig. 23  the cissoid of two curves with respect to O (OP = QR)
 * Fig. 24  the cissoid generated by a circle of radius a rolling along the line L
 * Fig. 25  the Peaucellier cell that draws a cissoid
 * Fig. 26  Newton's carpenter's square
 */

/* Fig. 23, page 26 — the general cissoid. Two given curves and the fixed point O. A variable
   secant through O meets them at Q and R; P is the point of the secant with OP = QR. The locus of P
   is the cissoid of the two curves with respect to O. */
Curves.figure({
  id: 'fig-023',
  section: 'cissoid',
  page: 26,
  title: 'The cissoid of two curves with respect to O',
  tags: ['cissoid', 'secant', 'construction'],
  note: 'The book draws the two given curves freehand and one secant only; here they are smooth arcs of the same shape, and the pencil step adds the locus of P.',
  build(k) {
    const g = k.g;
    // the two given curves, as x = f(y) arcs (freehand in the book)
    const x1 = y => 160 - 0.00398 * (y - 40) * (y - 40);
    const x2 = y => 243 + 0.00328 * (y - 175) * (y - 175);
    const bis = (f, lo, hi) => { let flo = f(lo); for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2, fm = f(m); if ((fm > 0) === (flo > 0)) { lo = m; flo = fm; } else hi = m; } return (lo + hi) / 2; };
    const O = k.pt(0, 0);
    const hit = (x, y0, y1, phi) => { const t = Math.tan(phi); const y = bis(yy => x(yy) - yy / t, y0, y1); return k.pt(y / t, y); };
    const Qof = phi => hit(x1, 6, 139, phi), Rof = phi => hit(x2, 20, 198, phi);
    const phi0 = g.deg(23);
    const Q = Qof(phi0), R = Rof(phi0);
    const u = g.dir(phi0);
    const P = g.add(O, g.mul(u, g.dist(Q, R)));               // OP = QR

    k.given('The fixed point O and the two given curves.', () => {
      k.curve(y => [x1(y), y], [6, 139], { cls: 'thick', n: 120 });
      k.curve(y => [x2(y), y], [20, 198], { cls: 'thick', n: 120 });
      k.pivot(O); k.label(O, 'O', 'n', { dist: 1.9 });
    });
    k.step('straightedge', 'Draw a secant through O. It meets the first curve at Q and the second at R.', () => {
      k.seg(O, g.add(O, g.mul(u, g.dist(O, R) + 34)));
      k.point(Q, 'Q', { at: 'ne', open: true });
      k.point(R, 'R', { at: 'ne', open: true });
    });
    k.step('dividers', 'Take the distance QR with the dividers and lay it off from O along the secant: OP = QR. P is a point of the cissoid.', () => {
      k.arc(O, g.dist(Q, R), phi0 - 0.12, phi0 + 0.12, { cls: 'aux' });
      k.point(P, 'P', { at: 'nw', open: true });
    });
    k.step('pencil', 'Repeat with other secants through O. The locus of P is the cissoid of the two curves with respect to O.', () => {
      const lo = g.deg(5), hi = g.deg(37);
      k.curve(phi => { const q = Qof(phi), r = Rof(phi); const d = g.dist(q, r); return [d * Math.cos(phi), d * Math.sin(phi)]; }, [lo, hi], { n: 120 });
    });
  }
});

/* Fig. 24, page 27 — the cissoid of the fixed circle (centre K, radius a, through O) and the line L
   at distance 2(a+b) from O. P is the second intersection of the secant OR with the circle of radius a
   that touches L at R, so OP = QR and r = 2(a+b) sec θ − 2a cos θ. */
Curves.figure({
  id: 'fig-024',
  section: 'cissoid',
  page: 27,
  title: 'The cissoid generated by a circle rolling on the line L',
  tags: ['cissoid', 'roulette', 'circle and line'],
  note: 'The book draws one position (θ about 20°) with b about 0.57a, so the curve has no cusp. With b = 0 the line L moves to 2a and the curve is the cissoid of Diocles.',
  build(k) {
    const g = k.g;
    const a = 100, b = 56.5, th = g.deg(20);
    const O = k.pt(0, 0), K = k.pt(a, 0), D = k.pt(2 * a, 0);
    const Lx = 2 * (a + b);
    const Lfoot = k.pt(Lx, 0);
    const R = k.pt(Lx, Lx * Math.tan(th));
    const u = g.dir(th);
    const Q = g.add(O, g.mul(u, 2 * a * Math.cos(th)));
    const P = g.add(O, g.mul(u, g.dist(O, R) - 2 * a * Math.cos(th)));
    const Cr = k.pt(Lx - a, R.y);                                // the centre of the circle of radius a rolling on L
    const r = t => 2 * (a + b) / Math.cos(t) - 2 * a * Math.cos(t);

    k.given('The fixed circle of radius a with centre K through O, the axis OX, and the line L perpendicular to it at distance 2(a + b) from O.', () => {
      k.seg(k.pt(-35, 0), k.pt(372, 0), { cls: 'axis', arrow: 'end' });
      k.label(k.pt(366, 0), 'X', 'n', { dist: 1.4, cls: 'axis' });
      k.circle(K, a);
      k.pivot(O); k.label(O, 'O', 'sw', { dist: 1.2 });
      k.point(K, 'K', { at: 's', open: true, lo: { dist: 1.4 } });
      k.point(D, '', { open: true });
      k.point(Lfoot, 'L', { at: 's', open: true, lo: { dist: 2.4 } });
      k.text(70, 9, 'a', { size: 0.95 });
      k.dim(D, Lfoot, '2b', { dist: 0.9 });
      k.seg(k.pt(Lx, -118), k.pt(Lx, 215), { cls: 'given' });
    });
    k.step('compass', 'Choose a point R on L and draw the circle of radius a that touches L at R: its centre lies a to the left of R, on the horizontal through R.', () => {
      k.seg(k.pt(Cr.x - a - 8, R.y), R);
      k.circle(Cr, a);
      k.point(Cr, '', { open: true });
      k.point(R, 'R', { at: 'e', open: true });
      k.dim(k.pt(Cr.x - a, R.y), Cr, 'a', { dist: 0.9 });
      k.dim(Cr, R, 'a', { dist: 0.9 });
    });
    k.step('straightedge', 'Draw OR. It cuts the fixed circle again at Q and the circle of radius a again at P. The chord RP of the moving circle equals 2a cos θ = OQ, so OP = QR: P is on the cissoid.', () => {
      k.seg(O, R);
      k.point(Q, 'Q', { at: 'n', open: true, lo: { dist: 1.5 } });
      k.point(P, 'P', { at: 'se', open: true, lo: { dist: 1.1 } });
    });
    k.note('The angle θ of the secant and its length r = OP.', () => {
      k.angle(O, k.pt(60, 0), R, { label: 'θ', r: 1.5, labelDist: 1.2 });
      k.label(g.mul(g.add(O, P), 0.5), 'r', 'n', { dist: 1.6 });
    });
    k.step('pencil', 'Move R along L. P traces the cissoid r = 2(a + b) sec θ − 2a cos θ, with L as its asymptote.', () => {
      k.curve(t => { const rr = r(t); return [rr * Math.cos(t), rr * Math.sin(t)]; }, [g.deg(-32), g.deg(37)], { n: 240, nobounds: true });
    });
  }
});

/* Fig. 25, page 28 — the Peaucellier cell. O and C are fixed pivots, OC = c. The bar CQ of length c
   keeps Q on the circle of radius c through O. Two long bars QA, QB (length L) and four short bars
   OA, OB, AP, BP (length s) make the cell; Q, O, P stay on one line and (OQ)(QP) = L² − s² = k². */
Curves.figure({
  id: 'fig-025',
  section: 'cissoid',
  page: 28,
  title: 'The Peaucellier cell that draws a cissoid',
  tags: ['linkage', 'inversion', 'Peaucellier'],
  note: 'The book draws the cell with k² = 1 and the angle θ at O; here the lengths are chosen so that the cell closes. The book does not draw the curve; the pencil step adds the path of P.',
  build(k) {
    const g = k.g;
    const c = 100, s = 149, th = g.deg(45);
    const O = k.pt(0, 0), C = k.pt(-c, 0);
    const OQ = 2 * c * Math.cos(th);
    const Q = g.mul(g.dir(Math.PI + th), OQ);
    const rr = 246;
    const P = g.mul(g.dir(th), rr);
    const L = Math.sqrt(s * s + OQ * (OQ + rr));
    const k2 = L * L - s * s;
    const cc = g.circleCircle(O, s, P, s);
    const A1 = cc[0].y > cc[1].y ? cc[0] : cc[1], B1 = cc[0].y > cc[1].y ? cc[1] : cc[0];
    k.pad(0.1);
    const blk = (p, w, h) => [k.pt(p.x - w, p.y - h), k.pt(p.x + w, p.y - h), k.pt(p.x + w, p.y + h), k.pt(p.x - w, p.y + h)];

    k.given('The two fixed pivots O and C on a line, at the distance c. C is the centre of a bar of length c.', () => {
      k.seg(k.pt(-146, 0), k.pt(212, 0), { cls: 'given', arrow: 'end' });
      k.poly(blk(O, 20, 16), { close: true, fill: '#fff' });
      k.poly(blk(C, 22, 17), { close: true, fill: '#fff' });
      k.pivot(O); k.pivot(C);
      k.label(O, 'O', 's', { dist: 2.6 });
      k.dim(C, O, 'c', { dist: 1.2 });
    });
    k.step('linkage', 'Hinge a bar CQ of length c at C. Its free end Q can only move on the circle of radius c about C, and that circle passes through O.', () => {
      k.arc(C, c, g.deg(-135), g.deg(25), { cls: 'aux', dash: true, nobounds: true });
      k.bar(C, Q);
      k.pivot(Q); k.label(Q, 'Q', 'w', { dist: 1.8 });
      k.dim(C, Q, 'c', { dist: 1.2, side: 'right' });
    });
    k.step('linkage', 'Hinge two long bars of length L at Q. Their other ends A and B are joined to O by two short bars of length s, and to P by two more short bars of length s: O, A, P, B is a rhombus.', () => {
      k.bar(Q, A1); k.bar(Q, B1);
      k.bar(O, A1); k.bar(O, B1);
      k.bar(A1, P); k.bar(B1, P);
      k.pivot(A1); k.pivot(B1); k.pivot(P);
      k.label(P, 'P', 'n', { dist: 2.2 });
      k.pivot(O);
    });
    k.note('Q, O and P are always on one line (the rhombus is symmetric about it), and (OQ)(QP) = L² − s² = k². With OQ = 2c cos θ and QP = 2c cos θ + r this gives the polar equation of the path of P.', () => {
      k.seg(Q, O, { cls: 'cons', dash: true });
      k.seg(O, P, { cls: 'cons', dash: true });
      k.angle(O, C, Q, { label: 'θ', r: 2.1, labelDist: 1.3 });
      k.angle(O, k.pt(60, 0), P, { label: 'θ', r: 2.1, labelDist: 1.3 });
      k.label(g.mul(P, 0.55), 'r', 'se', { dist: 1.0 });
    });
    k.step('pencil', 'Turn the cell. P draws the cissoid r = (k² / 2c) sec θ − 2c cos θ, which has no loop, a cusp or a loop as k² / 2c is greater than, equal to or less than 2c.', () => {
      k.curve(t => { const rv = (k2 / (2 * c)) / Math.cos(t) - 2 * c * Math.cos(t); return [rv * Math.cos(t), rv * Math.sin(t)]; }, [g.deg(-50), g.deg(58)], { n: 260, nobounds: true });
    });
  }
});

/* Fig. 26, page 28 — Newton's carpenter's square. The right angle of the square is at Q, one edge QA
   has length 2a and its end A runs along the line CA; the other edge passes through the fixed point B.
   Then AB = 2a sec θ and the point P of AQ with AP = b describes r = 2a sec θ − 2b cos θ.
   O is on BC with OB = b, BC = 2a. The centre of rotation H lies on the normals at A and B. */
Curves.figure({
  id: 'fig-026',
  section: 'cissoid',
  page: 28,
  title: "Newton's carpenter's square generating a cissoid",
  tags: ["carpenter's square", 'mechanical', 'tangent'],
  note: 'In the book the edge AQ is drawn a little shorter than BC = 2a; here the square is drawn to the stated lengths (AQ = BC = 2a, AP = OB = b). The book does not draw the curve; the pencil step adds the path of P.',
  build(k) {
    const g = k.g;
    const a2 = 200, b = 79, th = g.deg(54);                 // 2a, b = OB = AP, and θ
    const O = k.pt(0, 0), B = k.pt(-b, 0), C = k.pt(a2 - b, 0);
    const A = k.pt(C.x, a2 * Math.tan(th));
    const dQ = g.dir(Math.PI + 2 * th);
    const Q = g.add(A, g.mul(dQ, a2));
    const P = g.add(A, g.mul(dQ, b));
    const uA = g.unit(g.sub(A, Q)), uB = g.unit(g.sub(B, Q));
    const w = 17;                                           // the width of the square's arms
    const Bend = g.add(Q, g.mul(uB, g.dist(Q, B) + 52));    // the broken end of the long arm
    const H = g.lineLine(A, g.add(A, k.pt(-1, 0)), B, g.add(B, g.perp(uB)));
    const poly = [Q, A, g.add(A, g.mul(uB, w)), g.add(Q, g.mul(g.add(uA, uB), w)), g.add(Bend, g.mul(uA, w)), Bend];
    // the zigzag of the broken end
    const e0 = g.add(Bend, g.mul(uA, w)), e1 = Bend;
    const zig = [0.2, 0.4, 0.6, 0.8].map((t, i) => g.add(g.lerp(e0, e1, t), g.mul(uB, (i % 2 ? 4 : -4))));
    const shape = [poly[0], poly[1], poly[2], poly[3], poly[4], ...zig, poly[5]];
    const rectA = [Q, A, g.add(A, g.mul(uB, w)), g.add(Q, g.mul(uB, w))];
    const rectB = [Q, Bend, g.add(Bend, g.mul(uA, w)), g.add(Q, g.mul(uA, w))];
    const ccw = pts => { let s = 0; pts.forEach((p, i) => { const q = pts[(i + 1) % pts.length]; s += p.x * q.y - q.x * p.y; }); return s > 0 ? pts : pts.slice().reverse(); };
    const rects = [ccw(rectA), ccw(rectB)];
    // the parts of segment XY outside the square (the square is opaque in the book)
    const outside = (X, Y) => {
      const d = g.sub(Y, X), cuts = [];
      rects.forEach(pg => {
        let t0 = 0, t1 = 1;
        for (let i = 0; i < pg.length && t0 < t1; i++) {
          const p = pg[i], q = pg[(i + 1) % pg.length], e = g.sub(q, p);
          const num = g.cross(e, g.sub(X, p)), den = g.cross(e, d);
          if (Math.abs(den) < 1e-12) { if (num < 0) { t0 = 1; t1 = 0; } continue; }
          const t = -num / den; if (den > 0) t0 = Math.max(t0, t); else t1 = Math.min(t1, t);
        }
        if (t0 < t1) cuts.push([t0, t1]);
      });
      cuts.sort((m, n) => m[0] - n[0]);
      const out = []; let t = 0;
      cuts.forEach(([c0, c1]) => { if (c0 > t + 1e-9) out.push([t, c0]); t = Math.max(t, c1); });
      if (t < 1 - 1e-9) out.push([t, 1]);
      return out.map(([s0, s1]) => [g.lerp(X, Y, s0), g.lerp(X, Y, s1)]);
    };
    const seen = (X, Y, o) => outside(X, Y).forEach(([p, q]) => k.seg(p, q, o));
    const outN = g.mul(uB, -1);                             // away from the inside of the square
    const rcurve = t => 2 * (a2 / 2) / Math.cos(t) - 2 * b * Math.cos(t);

    k.given('The line BC with the fixed point B, the origin O (OB = b) and C (BC = 2a), and the line CA perpendicular to BC at C. The square will slide with its corner A on CA.', () => {
      k.seg(k.pt(B.x - 24, 0), k.pt(C.x + 92, 0), { cls: 'axis', arrow: 'end' });
      k.seg(C, k.pt(C.x, A.y + 30));
      k.point(B, 'B', { at: 's', open: true, lo: { dist: 1.4 } });
      k.point(O, 'O', { at: 's', open: true, lo: { dist: 1.4 } });
      k.point(C, 'C', { at: 'nw', open: true });
      k.text((B.x + O.x) / 2, -14, 'b', { size: 0.9 });
      k.text(90, -14, '2a − b', { size: 0.9 });
    });
    k.step('compass', 'Choose A on CA. Then Q is the point at distance 2a from A on the circle that has AB as diameter, so that the angle AQB is a right angle.', () => {
      k.seg(A, B, { cls: 'cons', dash: true });
      k.point(A, 'A', { at: 'ne', open: true });
      const Mab = g.mid(A, B), rr = g.dist(A, B) / 2;
      const aq = g.angleOf(g.sub(Q, Mab));
      k.arc(Mab, rr, aq - 0.35, aq + 0.35, { cls: 'cons' });
      const ap = g.angleOf(g.sub(Q, A));
      k.arc(A, a2, ap - 0.2, ap + 0.2, { cls: 'cons' });
    });
    k.step('square', 'Place the carpenter\'s square with its corner at Q: one edge runs from Q to A, the other passes through B. The right angle is at Q; AQ = 2a.', () => {
      k.seg(Q, A, { cls: 'given' });
      k.seg(Q, g.add(Q, g.mul(uB, g.dist(Q, B) + 52)), { cls: 'given' });
      k.hatch(shape, { angle: g.deg(60), gap: 0.5, fill: '#fff', outline: true });
      k.poly(shape, { close: true, cls: 'given' });
      k.poly([g.add(Q, g.mul(uA, 9)), g.add(g.add(Q, g.mul(uA, 9)), g.mul(uB, 9)), g.add(Q, g.mul(uB, 9)), Q], { close: true, fill: '#1b1b1b', cls: 'given', nobounds: true });
      k.label(Q, 'Q', 'se', { dist: 1.2 });
      k.dot(B, { open: true });
    });
    k.step('dividers', 'On AQ mark P with AP = b (the same distance as OB). P is the tracing point.', () => {
      k.point(P, 'P', { at: 'e', open: true, lo: { dist: 1.3 } });
      const mb = g.add(g.lerp(A, P, 0.5), g.mul(outN, 12)), mq = g.add(g.lerp(P, Q, 0.5), g.mul(outN, 24));
      k.text(mb.x, mb.y, 'b', { size: 0.9 });
      k.text(mq.x, mq.y, '2a − b', { size: 0.9 });
    });
    k.step('straightedge', 'Draw OP. It is parallel to AB and its direction θ is the angle ABC, so AB = 2a sec θ and OP = r = 2a sec θ − 2b cos θ.', () => {
      seen(O, P, { cls: 'given' });
      k.angle(O, k.pt(70, 0), P, { label: 'θ', r: 1.7, labelDist: 1.2 });
      k.label(g.lerp(O, P, 0.46), 'r', 'se', { dist: 1.0 });
      seen(A, B, { cls: 'cons', dash: true });
    });
    k.step('square', 'The centre of rotation H: the normal to CA at A (horizontal) meets the normal to BQ at B. HP is then the normal to the path of P.', () => {
      k.seg(A, H, { cls: 'given' });
      k.seg(B, H, { cls: 'given' });
      seen(H, P, { cls: 'given' });
      k.point(H, 'H', { at: 'se', open: true, lo: { dist: 1.3 } });
    });
    k.step('pencil', 'As the square slides, P draws the cissoid r = 2a sec θ − 2b cos θ (asymptote x = 2a). The point Q describes a strophoid.', () => {
      k.line(k.pt(a2, 0), k.pt(a2, 1), { cls: 'aux', dash: true, nobounds: true });
      k.curve(t => { const rv = rcurve(t); return [rv * Math.cos(t), rv * Math.sin(t)]; }, [g.deg(-42), g.deg(66)], { n: 260, nobounds: true });
    });
  }
});
